package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Notify the single granted channel with a summary of the digest.
        let message = format!(
            "digest {} published: {} ({} entries, {} considered)",
            composed.date,
            composed.overview,
            composed.entries.len(),
            composed.considered.len(),
        );
        let _ = crate::aap::caps::notifier::notify(&message);

        // ensures present(published): the payload reports a published digest.
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published: true,
        }
    }
}

export!(Node);
